package com.pawsshop;
import com.pawsshop.model.*; import com.pawsshop.repo.MessageRepository; import com.pawsshop.service.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ExtendedDomainTest {
 @Test void userRolesAndDashboardArePolymorphic(){User a=new Admin(),d=new Doctor(),c=new CustomerAccount();assertEquals("/dashboard/admin",a.getDashboardPath());assertEquals("/dashboard/doctor",d.getDashboardPath());assertEquals("CUSTOMER",c.getRole());}
 @Test void serviceAndPetBehavePolymorphically(){PetService grooming=new PetGrooming(),vet=new VetConsultation();assertTrue(grooming.getServiceDetails().contains("nail"));assertTrue(vet.getServiceDetails().contains("Clinical"));Pet dog=new Dog(),cat=new Cat();assertNotEquals(dog.getCareAdvice(),cat.getCareAdvice());}
 @Test void appointmentTransitions(){AppointmentWorkflow w=new AppointmentWorkflow();assertDoesNotThrow(()->w.validateTransition("PENDING","CONFIRMED"));assertDoesNotThrow(()->w.validateTransition("CONFIRMED","COMPLETED"));assertThrows(IllegalArgumentException.class,()->w.validateTransition("CANCELLED","CONFIRMED"));assertThrows(IllegalArgumentException.class,()->w.validateTransition("PENDING","COMPLETED"));}
 @Test void validMessageIsSavedAndInvalidIsRejected(){MessageRepository repo=mock(MessageRepository.class);when(repo.save(any(Message.class))).thenAnswer(i->i.getArgument(0));MessageService service=new MessageService(repo);Message m=new Message();m.setName("Jane");m.setEmail("jane@example.com");m.setBody("Hello");Message saved=service.submit(m);assertNotNull(saved.getCreatedAt());assertFalse(saved.isResolved());verify(repo).save(m);Message bad=new Message();assertThrows(IllegalArgumentException.class,()->service.submit(bad));}
}
